import 'dart:typed_data';

import 'package:crisp_cloud/services/aes_siv.dart';
import 'package:flutter_test/flutter_test.dart';

Uint8List _hex(String value) => Uint8List.fromList([
  for (var i = 0; i < value.length; i += 2)
    int.parse(value.substring(i, i + 2), radix: 16),
]);

void main() {
  // Independent published known-answer tests, not ciphertext generated by
  // this implementation: https://www.rfc-editor.org/rfc/rfc5297#appendix-A
  test('RFC 5297 appendix A.1, short plaintext and masked counter', () {
    final macKey = _hex('fffefdfcfbfaf9f8f7f6f5f4f3f2f1f0');
    final encKey = _hex('f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff');
    final ad = [_hex('101112131415161718191a1b1c1d1e1f2021222324252627')];
    final plaintext = _hex('112233445566778899aabbccddee');
    final encrypted = _hex(
      '85632d07c6e8f37f950acd320a2ecc9340c02b9690c4dc04daef7f6afe5c',
    );
    expect(
      AesSiv.encrypt(plaintext, encKey, macKey, associatedData: ad),
      encrypted,
    );
    expect(
      AesSiv.decrypt(encrypted, encKey, macKey, associatedData: ad),
      plaintext,
    );
  });

  test('RFC 5297 appendix A.2, multiple AD strings and long plaintext', () {
    final macKey = _hex('7f7e7d7c7b7a79787776757473727170');
    final encKey = _hex('404142434445464748494a4b4c4d4e4f');
    final ad = [
      _hex(
        '00112233445566778899aabbccddeeffdeaddadadeaddadaffeeddccbbaa9988'
        '7766554433221100',
      ),
      _hex('102030405060708090a0'),
      _hex('09f911029d74e35bd84156c5635688c0'),
    ];
    final plaintext = _hex(
      '7468697320697320736f6d6520706c61696e7465787420746f20656e63727970'
      '74207573696e67205349562d414553',
    );
    final encrypted = _hex(
      '7bdb6e3b432667eb06f4d14bff2fbd0fcb900f2fddbe404326601965c889bf17'
      'dba77ceb094fa663b7a3f748ba8af829ea64ad544a272e9c485b62a3fd5c0d',
    );
    expect(
      AesSiv.encrypt(plaintext, encKey, macKey, associatedData: ad),
      encrypted,
    );
    expect(
      AesSiv.decrypt(encrypted, encKey, macKey, associatedData: ad),
      plaintext,
    );
  });

  test('rejects tag, ciphertext, associated-data and key changes', () {
    final encKey = _hex('f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff');
    final macKey = _hex('fffefdfcfbfaf9f8f7f6f5f4f3f2f1f0');
    final ad = [_hex('101112131415161718191a1b1c1d1e1f2021222324252627')];
    final encrypted = _hex(
      '85632d07c6e8f37f950acd320a2ecc9340c02b9690c4dc04daef7f6afe5c',
    );
    for (final offset in [0, 15, 16, encrypted.length - 1]) {
      final tampered = Uint8List.fromList(encrypted)..[offset] ^= 1;
      expect(
        () => AesSiv.decrypt(tampered, encKey, macKey, associatedData: ad),
        throwsFormatException,
      );
    }
    expect(
      () => AesSiv.decrypt(encrypted, encKey, macKey),
      throwsFormatException,
    );
    expect(
      () => AesSiv.decrypt(encrypted, macKey, encKey, associatedData: ad),
      throwsFormatException,
    );
  });

  test('does not collapse distinct associated-data strings', () {
    final key = Uint8List(32);
    final data = Uint8List.fromList([1, 2, 3]);
    final encrypted = AesSiv.encrypt(
      data,
      key,
      key,
      associatedData: [
        Uint8List.fromList([4]),
        Uint8List.fromList([5, 6]),
      ],
    );
    expect(
      () => AesSiv.decrypt(
        encrypted,
        key,
        key,
        associatedData: [
          Uint8List.fromList([4, 5]),
          Uint8List.fromList([6]),
        ],
      ),
      throwsFormatException,
    );
  });

  test('validates key lengths, input length and S2V input limit', () {
    final key = Uint8List(32);
    expect(
      () => AesSiv.encrypt(Uint8List(0), key, Uint8List(16)),
      throwsArgumentError,
    );
    expect(
      () => AesSiv.decrypt(Uint8List(15), key, key),
      throwsFormatException,
    );
    expect(
      () => AesSiv.encrypt(
        Uint8List(0),
        key,
        key,
        associatedData: List.generate(127, (_) => Uint8List(0)),
      ),
      throwsArgumentError,
    );
  });
}
